<?php
require __DIR__.'/app-bootstrap.php';
$u=require_admin();require $privateRootPath.'/src/admin_payout_layout.php';
$history=$pdo->query("SELECT p.*,u.display_name user_name,u.email user_email,(SELECT GROUP_CONCAT(DISTINCT a.name ORDER BY a.name SEPARATOR ', ') FROM artist_payout_items api2 JOIN artists a ON a.id=api2.artist_id WHERE api2.payout_id=p.id) artist_names FROM artist_payouts p LEFT JOIN artists a_owner ON a_owner.id=p.artist_id LEFT JOIN users u ON u.id=COALESCE(p.user_id,a_owner.owner_user_id) ORDER BY p.created_at DESC,p.id DESC LIMIT 500")->fetchAll();admin_payout_layout_start('history');admin_payout_flash();
?>
<div class="section-title"><div><span class="kicker">ARTIST ACCOUNTING</span><h1>Payout History</h1></div><span><?=count($history)?> payments</span></div><section class="panel admin-list-panel"><div class="admin-section-head"><h2>All payments</h2><span>Manual and automatic</span></div><div class="admin-table payout-history"><div class="admin-row user-admin-head"><strong>User</strong><strong>Artist aliases</strong><strong>Period</strong><strong>Amount</strong><strong>PayPal batch</strong><strong>Status</strong></div><?php foreach($history as $item):?><div class="admin-row"><span><strong><?=e($item['user_name']?:'Unassigned')?></strong><?php if(!empty($item['user_email'])):?><small><?=e($item['user_email'])?></small><?php endif;?></span><span><?=e($item['artist_names']?:'—')?></span><span><?=e($item['period_start'])?> → <?=e($item['period_end'])?></span><span><?=money((int)$item['payout_pence'])?></span><span><?=e($item['paypal_batch_id']?:'Manual')?></span><span class="badge <?=e($item['status'])?>"><?=e(ucfirst($item['status']))?><?php if(!empty($item['error_message'])):?><small><?=e($item['error_message'])?></small><?php endif;?></span></div><?php endforeach;?><?php if(!$history):?><p class="muted">No payouts have been recorded yet.</p><?php endif;?></div></section><?php admin_payout_layout_end();
